function openLogin(){$('#login-step-2').classList.add('hidden');$('#login-step-1').classList.remove('hidden');$('#login-email').value='';$('#password').value='';if(IS_APP_DOMAIN){$('#marketing').classList.add('hidden');$('.topbar').classList.add('hidden');$('#login-modal').classList.add('portal-login');$('#login-modal .close').classList.add('hidden');document.body.style.overflow='hidden'}$('#login-modal').classList.remove('hidden');setTimeout(()=>$('#login-email').focus(),50)}
function closeDrawer(){$('#app').classList.remove('drawer-open');$('.app-menu').setAttribute('aria-expanded','false')}function openDrawer(){$('#app').classList.add('drawer-open');$('.app-menu').setAttribute('aria-expanded','true')}
function identity(){const name=state.profile?.full_name||state.user?.email?.split('@')[0]||'Usuário',company=state.company?.name||(state.profile?.is_global_admin?'Administração MD Flux':'Minha empresa');$('#profile-name').textContent=name;$('#profile-role').textContent=state.profile?.is_global_admin?'Administrador global':label(state.role||'Usuário');$('#profile-initials').textContent=name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();$('#company-name').textContent=company;$('#company-plan').textContent=state.mode==='demo'?'Plano Completo':state.profile?.is_global_admin?'Acesso global':'Ambiente seguro';$('#company-initials').textContent=company.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
async function enterApp(){document.activeElement?.blur();$('#marketing').classList.add('hidden');$('.topbar').classList.add('hidden');$('#login-modal').classList.add('hidden');$('#app').classList.remove('hidden');document.body.style.overflow='hidden';identity();state.module='Dashboard';buildNav();renderDashboard();requestAnimationFrame(()=>{$('.app-body').scrollTop=0;scrollTo(0,0)})}
async function signIn(){const login=$('#login-email').value.trim().toLowerCase(),password=$('#password').value,b=$('#submit-login');if(!password)return toast('Informe sua senha.','error');b.disabled=true;b.textContent='Entrando…';try{if(CONFIG.demoUsers.some(u=>u.login===login&&u.password===password)){state.mode='demo';state.user=null;state.profile={full_name:'Mariana Silva'};state.company={name:'Loja Florescer',id:'demo'};state.role='admin';return enterApp()}if(!login.includes('@'))throw Error('Para uma conta real, informe o e-mail completo.');if(!db)throw Error('Não foi possível iniciar a conexão segura.');Object.assign(state,{mode:'real',user:null,profile:null,company:null,role:null});const auth=await db.auth.signInWithPassword({email:login,password});if(auth.error)throw Error('E-mail ou senha inválidos.');state.user=auth.data.user;const p=await db.from('profiles').select('full_name,is_global_admin').eq('id',state.user.id).maybeSingle();if(p.error)throw Error('Perfil não carregado. Execute a migration 002.');state.profile=p.data||{full_name:login.split('@')[0]};const m=await db.from('company_users').select('role,company_id,companies(id,name,status)').eq('user_id',state.user.id).eq('status','active').limit(1).maybeSingle();if(m.data){state.role=m.data.role;state.company=m.data.companies}if(!state.profile.is_global_admin&&!state.company)throw Error('Usuário autenticado, mas ainda não vinculado a uma empresa.');if(state.company?.status==='suspended')throw Error('Seu acesso está temporariamente suspenso.');await enterApp();toast('Login realizado com segurança.','success')}catch(e){toast(e.message,'error')}finally{b.disabled=false;b.textContent='Entrar'}}
async function signOut(){if(state.mode==='real'&&db)await db.auth.signOut();Object.assign(state,{mode:'guest',user:null,profile:null,company:null,role:null,module:'Dashboard',rows:[],editing:null});$('#app').classList.add('hidden');closeDrawer();if(IS_APP_DOMAIN)openLogin();else{$('#marketing').classList.remove('hidden');$('.topbar').classList.remove('hidden');document.body.style.overflow=''}}
const quick=(i,t,d,m)=>`<button class="quick-card" data-module="${m}"><span>${icon(i)}</span><b>${t}</b><small>${d}</small><i>${icon('arrow')}</i></button>`;
function renderDashboard(){state.module='Dashboard';buildNav();$('#app-content').innerHTML=`${state.mode==='demo'?'<div class="notice">Ambiente de demonstração: explore livremente. Alterações não serão salvas.</div>':''}<div class="welcome"><div><span class="page-kicker">INÍCIO</span><h1>O que você quer fazer?</h1><p>Acesse rapidamente as tarefas mais usadas ou consulte os números do negócio.</p></div><button class="primary quick-new">${icon('plus')} Novo lançamento</button></div><section class="quick-section"><h2>Acesso rápido</h2><div class="quick-grid">${quick('finance','Lançar no financeiro','Registre uma entrada ou saída','Financeiro')}${quick('clients','Consultar clientes','Cadastre ou encontre um cliente','Clientes')}${quick('sales','Registrar venda','Crie uma nova movimentação','Vendas')}${quick('calendar','Abrir agenda','Veja seus compromissos','Agenda')}${quick('products','Produtos e serviços','Consulte preços e cadastros','Produtos e serviços')}${quick('reports','Gerar relatório','Analise e exporte dados','Relatórios')}</div></section><div class="section-heading"><div><h2>Resumo do negócio</h2><p>Visão dos últimos 30 dias</p></div><div class="filters"><button>Hoje</button><button>7 dias</button><button class="active">30 dias</button><button>Este mês</button></div></div><div class="kpi-grid">${[['Saldo atual','R$ 48.320,00','↑ 12,5%','finance'],['Entradas','R$ 31.840,00','↑ 8,2%','sales'],['Saídas','R$ 12.460,00','↓ 3,1%','finance'],['Vendas','86','↑ 14,8%','sales']].map(k=>`<article class="kpi"><div><span>${k[0]}</span><i>${icon(k[3])}</i></div><strong>${k[1]}</strong><small>${k[2]} no período</small></article>`).join('')}</div><div class="dash-grid"><article class="panel"><div class="panel-head"><h3>Fluxo de caixa</h3><small>Últimos 7 meses</small></div><div class="chart-large">${[40,63,52,79,68,92,83].map(x=>`<i style="height:${x}%"></i>`).join('')}</div></article><article class="panel"><div class="panel-head"><h3>Próximos compromissos</h3><button class="link-button" data-module="Agenda">Ver agenda</button></div>${DEMO.Agenda.map(r=>`<div class="list-row"><b>${r[0]}</b><span>${r[1]}</span><small>${r[2]}</small><span>${r[3]}</span></div>`).join('')}</article></div>`;$('.quick-new').onclick=()=>openRecord('Financeiro');filters()}
async function rowsFor(name){if(state.mode==='demo'||!state.company?.id||!SOURCES[name])return(DEMO[name]||[['Relatório mensal','Período atual','Atualizado agora','Disponível']]).map((r,i)=>[...r,`demo-${i}`]);const s=SOURCES[name],q=await db.from(s.table).select(s.select).eq('company_id',state.company.id).limit(100);if(q.error){toast('Consulta bloqueada. Verifique sua permissão.','error');return[]}return q.data.map(s.map)}
async function renderModule(name){if(name==='Dashboard')return renderDashboard();state.module=name;buildNav();closeDrawer();if(name==='Administração')return renderAdmin();$('#app-content').innerHTML='<div class="loading-card">Carregando informações…</div>';const rows=await rowsFor(name);state.rows=rows;$('#app-content').innerHTML=`<div class="module-head"><div><span class="page-kicker">MÓDULO</span><h1>${name}</h1><p>Pesquise, consulte e organize suas informações.</p></div><button class="primary new-record">${icon('plus')} Adicionar</button></div><div class="module-command"><label class="module-search">${icon('search')}<input placeholder="Pesquisar neste módulo…"></label><div class="export-actions"><button data-format="csv">CSV</button><button data-format="xlsx">Excel</button><button data-format="pdf">PDF</button><button data-format="doc">Word</button></div></div><div class="filters"><button class="active">Todos</button><button>Ativos</button><button>Pendentes</button><button>Este mês</button></div>${rows.length?`<div class="table-card"><div class="data-row table-header"><span>Descrição</span><span>Detalhes</span><span>Valor / data</span><span>Status</span><span>Ações</span></div><div class="rows-container">${rows.map(rowHtml).join('')}</div></div>`:`<div class="empty-state">${icon('search')}<h3>Nenhum registro encontrado</h3><p>Use Adicionar para começar.</p></div>`}`;$('.new-record').onclick=()=>openRecord(name);$('.module-search').oninput=e=>filterRows(e.target.value);$$('.export-actions button').forEach(b=>b.onclick=()=>exportData(name,rows,b.dataset.format));filters();actions()}
const rowHtml=r=>`<div class="data-row" data-search="${r.slice(0,4).join(' ').toLowerCase()}" data-id="${r[4]||''}"><b>${r[0]}</b><span>${r[1]}</span><span>${r[2]}</span><span class="status">${r[3]}</span><span class="row-actions"><button class="edit-row" aria-label="Editar">${icon('edit')}</button><button class="delete-row" aria-label="Excluir">${icon('trash')}</button></span></div>`;
function filterRows(v){const t=v.toLowerCase();$$('.rows-container .data-row').forEach(r=>r.classList.toggle('hidden',!r.dataset.search.includes(t)))}function demoBlocked(){toast('Na demonstração você pode consultar, mas não alterar dados.')}
function actions(){$$('.edit-row').forEach(b=>b.onclick=()=>{if(state.mode==='demo')return demoBlocked();state.editing=b.closest('.data-row').dataset.id;openRecord(state.module,b.closest('.data-row').querySelector('b').textContent)});$$('.delete-row').forEach(b=>b.onclick=async()=>{if(state.mode==='demo')return demoBlocked();if(!confirm('Deseja excluir este registro?'))return;const s=SOURCES[state.module],r=b.closest('.data-row');if(!s)return toast('Ação indisponível neste módulo.','error');const q=await db.from(s.table).delete().eq('id',r.dataset.id).eq('company_id',state.company.id);if(q.error)return toast('Exclusão bloqueada pela segurança.','error');toast('Registro excluído.','success');renderModule(state.module)})}
function openRecord(m,v=''){state.module=m;$('#record-title').textContent=state.editing?'Editar registro':`Adicionar em ${m}`;$('#record-form input').value=v;$('#record-modal').classList.remove('hidden')}
async function saveRecord(e){e.preventDefault();if(state.mode==='demo'){$('#record-modal').classList.add('hidden');return demoBlocked()}const s=SOURCES[state.module];if(!s||!state.company)return toast('Este cadastro exige um fluxo específico.','error');const f=e.target.elements,d=f[0].value.trim(),v=Number(f[2].value||0),dt=f[3].value||new Date().toISOString().slice(0,10);let p={company_id:state.company.id};if(state.module==='Financeiro')p={...p,description:d,type:'income',amount:v,transaction_date:dt,status:'pending'};else if(state.module==='Clientes')p={...p,name:d,status:'active'};else if(state.module==='Agenda')p={...p,title:d,starts_at:new Date(dt+'T12:00:00').toISOString(),status:'pending'};else if(state.module==='Produtos e serviços')p={...p,name:d,sale_price:v,status:'active'};else return toast('Use o cadastro específico deste módulo.','error');const q=state.editing?await db.from(s.table).update(p).eq('id',state.editing).eq('company_id',state.company.id):await db.from(s.table).insert(p);if(q.error)return toast('Operação bloqueada. Confira sua permissão.','error');state.editing=null;$('#record-modal').classList.add('hidden');toast('Registro salvo.','success');renderModule(state.module)}
function renderAdmin(){$('#app-content').innerHTML=`<div class="module-head"><div><span class="page-kicker">SEGURANÇA</span><h1>Administração global</h1><p>Ambiente exclusivo do MD Flux.</p></div></div><div class="admin-grid"><article>${icon('clients')}<h3>Empresas</h3><p>Planos e suspensões.</p></article><article>${icon('team')}<h3>Usuários</h3><p>Vínculos e perfis.</p></article><article>${icon('shield')}<h3>Permissões</h3><p>Ações por módulo.</p></article></div><div class="security-note">${icon('shield')}<div><b>Proteção ativa</b><p>Supabase Auth e RLS validam este acesso.</p></div></div>`}
function exportData(name,rows,fmt){const h=['Descrição','Detalhes','Valor ou data','Status'],d=rows.map(r=>r.slice(0,4));if(fmt==='doc')return exportDocx(name,h,d);if(fmt==='csv')download(new Blob(['\ufeff'+[h,...d].map(r=>r.map(x=>`"${x}"`).join(';')).join('\n')],{type:'text/csv'}),file(name,'csv'));if(fmt==='xlsx'&&window.XLSX){const w=XLSX.utils.aoa_to_sheet([h,...d]),b=XLSX.utils.book_new();XLSX.utils.book_append_sheet(b,w,name.slice(0,31));XLSX.writeFile(b,file(name,'xlsx'))}if(fmt==='pdf'&&window.jspdf){const p=new jspdf.jsPDF();p.text(`MD Flux — ${name}`,14,18);d.forEach((r,i)=>p.text(r.join(' | ').slice(0,105),14,30+i*7));p.save(file(name,'pdf'))}toast('Relatório gerado.','success')}
function exportDocx(name,headers,rows){if(!window.PizZip)return toast('O exportador Word não carregou. Tente novamente.','error');const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));const paragraph=t=>`<w:p><w:r><w:t>${esc(t)}</w:t></w:r></w:p>`;const body=[`MD Flux — ${name}`,'',headers.join(' | '),...rows.map(r=>r.join(' | '))].map(paragraph).join('');const zip=new PizZip();zip.file('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');zip.folder('_rels').file('.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');zip.folder('word').file('document.xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${body}<w:sectPr/></w:body></w:document>`);download(zip.generate({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}),file(name,'docx'));toast('Relatório DOCX gerado.','success')}
const file=(n,e)=>n.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,'-')+'.'+e;function download(b,n){const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function filters(){$$('.filters button').forEach(b=>b.onclick=()=>{b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');toast(`Filtro “${b.textContent}” aplicado`)})}
document.addEventListener('click',e=>{const m=e.target.closest('[data-module]');if(m)return renderModule(m.dataset.module);const a=e.target.closest('[data-action]');if(!a)return;const x=a.dataset.action;if(x==='demo'||x==='login')openLogin();if(x==='close'&&!IS_APP_DOMAIN)$('#login-modal').classList.add('hidden');if(x==='exit')signOut();if(x==='close-record'){$('#record-modal').classList.add('hidden');state.editing=null}if(x==='whatsapp')open(`https://wa.me/${CONFIG.whatsapp}?text=`+encodeURIComponent('Olá! Conheci o MD Flux e gostaria de saber mais.'),'_blank')});
$$('.faq-q').forEach(q=>q.onclick=()=>{const p=q.nextElementSibling,o=!p.classList.contains('hidden');p.classList.toggle('hidden');q.querySelector('i').textContent=o?'+':'−'});$('#continue-login').onclick=()=>{if(!$('#login-email').value.trim())return toast('Informe seu e-mail ou usuário.');$('#login-step-1').classList.add('hidden');$('#login-step-2').classList.remove('hidden');setTimeout(()=>$('#password').focus(),50)};$('.back-login').onclick=()=>{$('#login-step-2').classList.add('hidden');$('#login-step-1').classList.remove('hidden')};$('#show-pass').onclick=e=>{e.preventDefault();$('#password').type=$('#password').type==='password'?'text':'password'};$('#submit-login').onclick=signIn;$('#login-email').onkeydown=e=>{if(e.key==='Enter')$('#continue-login').click()};$('#password').onkeydown=e=>{if(e.key==='Enter')signIn()};$('#record-form').onsubmit=saveRecord;
$('.app-menu').onclick=()=>$('#app').classList.contains('drawer-open')?closeDrawer():openDrawer();$('.sidebar-close').onclick=closeDrawer;$('.sidebar-overlay').onclick=closeDrawer;$('#notif').onclick=()=>toast('3 notificações: estoque baixo, conta vencendo e agendamento próximo.');$('#global-search').oninput=e=>state.module!=='Dashboard'&&filterRows(e.target.value);$('.menu').onclick=()=>$('.topbar').classList.toggle('nav-open');addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();$('#record-modal').classList.add('hidden')}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#global-search')?.focus()}});
$('#continue-login').addEventListener('click',()=>{const login=$('#login-email').value.trim().toLowerCase(),demo=CONFIG.demoUsers.some(u=>u.login===login);$('.tenant i').textContent=demo?'LF':'MD';$('.tenant small').textContent=demo?'AMBIENTE DE DEMONSTRAÇÃO':'ACESSO SEGURO';$('.tenant b').textContent=demo?'Loja Florescer':'MD Flux'});
(async()=>{if(IS_APP_DOMAIN)openLogin();if(db){const s=await db.auth.getSession();if(s.data.session){state.mode='real';state.user=s.data.session.user;const p=await db.from('profiles').select('full_name,is_global_admin').eq('id',state.user.id).maybeSingle();state.profile=p.data;if(state.profile){const m=await db.from('company_users').select('role,company_id,companies(id,name,status)').eq('user_id',state.user.id).eq('status','active').limit(1).maybeSingle();if(m.data){state.role=m.data.role;state.company=m.data.companies}if(IS_APP_DOMAIN)enterApp()}}}})();
